# Forward-chaining check of: does the mermaid stop the victory of the zebra?
# Standard library only. No I/O beyond print.

PRIMARY_COLORS = {"red", "green", "blue"}  # source-domain convention; question gives no override

# Initial game state, restricted to facts relevant to the query
facts = {
    "~finch_builds_power_plant_near_mermaid_green_fields",  # stated: finch does NOT build near mermaid's green fields
    "mermaid_card_color:green",                             # stated: mermaid has a green card
}

def rule1(f):
    # If finch does not build near mermaid's green fields, mermaid shouts at cougar.
    if "~finch_builds_power_plant_near_mermaid_green_fields" in f:
        return {"mermaid_shouts_at_cougar"}
    return set()

def rule3(f):
    # If mermaid has a card with a primary color, mermaid does not acquire a photo of the fangtooth.
    for color in PRIMARY_COLORS:
        if f"mermaid_card_color:{color}" in f:
            return {"~mermaid_acquires_fangtooth_photo"}
    return set()

def rule8(f):
    # If an animal shouts at cougar and does not acquire a fangtooth photo, it stops the victory of the zebra.
    if "mermaid_shouts_at_cougar" in f and "~mermaid_acquires_fangtooth_photo" in f:
        return {"mermaid_stops_victory_zebra"}
    return set()

RULES = [rule1, rule3, rule8]

# Compute fixpoint
closure = set(facts)
changed = True
steps = 0
while changed and steps < 100:
    changed = False
    steps += 1
    for rule in RULES:
        new = rule(closure) - closure
        if new:
            closure |= new
            changed = True

derived = closure - facts
print("Derived facts:")
for d in sorted(derived):
    print("  ", d)

target = "mermaid_stops_victory_zebra"
negated_target = "~mermaid_stops_victory_zebra"

# Consistency check: no derivation of both a fact and its negation
conflicts = {x for x in closure if x.startswith("~") and x[1:] in closure}
print("Conflicts:", conflicts if conflicts else "none")

proved = target in closure and negated_target not in closure
disproved = negated_target in closure and target not in closure

if proved:
    computed = "proved"
elif disproved:
    computed = "disproved"
else:
    computed = "unknown"

print("Computed verdict:", computed)

submitted = "proved"  # submitted answer "proved**", normalized to the bare label
print("Submitted verdict:", submitted)

if computed == submitted and not conflicts:
    print("CHECK PASS")
elif computed == "unknown":
    print("CHECK UNKNOWN")
else:
    print("CHECK FAIL")
